def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0.0)
    my_no_water_days = my_status.get('no_water_days', 0)

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', True):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine a target bid level. If others were bidding aggressively yesterday,
    # we raise slightly to avoid losing the water allocation.
    # Keep our bid capped so we don't bankrupt early.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 1.1:
        pressure = 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.8:
        pressure = 0.5
    else:
        pressure = 0.3

    # If we are at risk (low hp or many no-water days), bid higher.
    risk = 0.0
    if my_hp <= 2:
        risk = 1.0
    elif my_hp <= 4:
        risk = 0.75
    elif my_hp <= 6:
        risk = 0.5
    else:
        risk = 0.25

    # Also react if we've already accumulated no-water days.
    if my_no_water_days >= 3:
        risk = max(risk, 0.9)
    elif my_no_water_days == 2:
        risk = max(risk, 0.7)

    # Base bid depends on supply: with more supply, we can bid a bit less.
    # supply is in [15,25]. Normalize to [0,1].
    try:
        supply_norm = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    except Exception:
        supply_norm = 0.5
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Higher supply => lower bid.
    supply_factor = 1.0 - 0.25 * supply_norm

    # Target: around 0.9*DAILY_SALARY when risky; otherwise around 0.55*DAILY_SALARY.
    target = (DAILY_SALARY * (0.55 + 0.4 * risk)) * (0.85 + 0.3 * pressure) * supply_factor

    # Additional nudge: if yesterday highest bid was very high, try to slightly over it but not too much.
    if highest_prev_bid > 0:
        target = max(target, min(my_budget, highest_prev_bid * 0.98))

    # Final bid constraints
    # Keep a floor to avoid being dominated; keep a ceiling to preserve budget.
    floor_bid = DAILY_SALARY * (0.35 + 0.25 * pressure)
    ceil_bid = DAILY_SALARY * (1.35 + 0.25 * risk)

    bid = max(floor_bid, min(target, ceil_bid))
    bid = min(bid, my_budget)

    # If budget is extremely low, just bid what we can.
    if my_budget <= DAILY_SALARY * 0.2:
        return max(0.0, my_budget)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            yesterday_bids.append(trace['bid'])

    base_bid = DAILY_SALARY * 0.5  # default
    # Adjust based on health
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 5:
        base_bid = DAILY_SALARY * 0.65
    else:
        base_bid = DAILY_SALARY * 0.4

    # Respond to opponent pressure from yesterday
    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        # If opponent was very aggressive, we may need to raise
        if max_yesterday > DAILY_SALARY * 0.85 and (hp <= 3 or supply < 18):
            base_bid = max(base_bid, max_yesterday * 0.9)
        else:
            # If they were moderate, try to undercut a bit
            base_bid = min(base_bid, max_yesterday * 0.8)

    # Cap by budget and sanity
    bid = max(1.0, min(budget, base_bid))
    # If supply is very low and hp low, go all in
    if supply <= MIN_SUPPLY + 2 and hp <= 3:
        bid = min(budget, DAILY_SALARY * 1.0)
    return float(bid)
